vec2 hash2(vec2 p)
{
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.y;
    vec2 g = uv * 6.0;
    vec2 cell = floor(g);
    vec2 f = fract(g);
    float best = 8.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 o = vec2(float(i), float(j));
            vec2 pt = hash2(cell + o);
            pt = 0.5 + 0.5 * sin(iTime * 0.8 + 6.2831 * pt);
            best = min(best, length(o + pt - f));
        }
    }
    vec3 col = mix(vec3(0.95, 0.80, 0.35), vec3(0.10, 0.25, 0.55), smoothstep(0.0, 0.8, best));
    fragColor = vec4(col, 1.0);
}
